python3 -c "
from pptx import Presentation
prs = Presentation('/app/output/final_deck.pptx')

# Verify key content on each slide
for i, slide in enumerate(prs.slides):
    texts = []
    for shape in slide.shapes:
        if shape.has_text_frame:
            for p in shape.text_frame.paragraphs:
                t = p.text.strip()
                if t:
                    texts.append(t)
        if shape.has_table:
            texts.append('[TABLE]')
        if shape.has_chart:
            texts.append('[CHART]')
    # Print first few text items
    preview = ' | '.join(texts[:5])
    print(f'Slide {i+1}: {preview[:150]}')
"

